    const product = productResult.value;
    processedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: effectiveDiscount,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: processedLines,
  });
}

/**
 * Calculate the total amount for a line (qty × unitPrice in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  const discount = total * (discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const total = Math.max(0, subtotal - discount);
  return {
    subtotal,
    discount,
    total,
  };
}

/**
 * Add or increment a line on an invoice.
 * @param {object} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discount (only if explicitly provided)
  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return fail('UNKNOWN_SKU');

  // Get customer to apply tier discount if needed
  const customerResult = getCustomer(invoice.customerId);
  const customer = customerResult.value;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += qty;
  } else {
    // Determine discount: explicit value or tier-based
    const effectiveDiscount = discountPercent !== undefined ? discountPercent : TIER_DISCOUNTS[customer.tier];

    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: effectiveDiscount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {object} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);
  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and marking it issued.
 * @param {object} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already issued
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

